import{_ as i,l as n,o as e,c as l,v as t,p as s,x as r,d as p,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"端口扫描与 Nmap","description":"","frontmatter":{"title":"端口扫描与 Nmap","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/port-scanning.md","filePath":"cs/port-scanning.md","lastUpdated":1789023840000}'),h={name:"cs/port-scanning.md"};function m(_,a,E,u,f,B){const o=n("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="端口扫描与-nmap" tabindex="-1">端口扫描与 Nmap <a class="header-anchor" href="#端口扫描与-nmap" aria-label="Permalink to &quot;端口扫描与 Nmap&quot;">​</a></h1><div class="epigraph"><p>扫描是问哪些传输端点在听。防御侧用它做资产盘点；同一技术也被侦察使用。课程讲可见性与减少暴露，不把扫描写成对他人网络的操作指南。</p><footer>—— 据 Fyodor, Nmap Network Scanning；对照 RFC 793 对连接状态的语义</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/ddos-mitigation">DDoS</a>是过量。缺口是<strong>发现</strong>：暴露了哪些端口。本课从资产与加固角度谈扫描，不提供对未授权目标的扫描步骤。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>只开必要端口。扫描自己的范围以核对防火墙。缺口是：影子 IT、IPv6、出站也要盘。Nmap 是常见实现名字，机制是探测与指纹——指纹用于识别过时服务以便补丁。</p><h3 id="授权" tabindex="-1">授权 <a class="header-anchor" href="#授权" aria-label="Permalink to &quot;授权&quot;">​</a></h3><p>只扫你有权扫的范围。外网扫描别人是另一回事。</p><p><span class="marginnote">Fyodor 的书是工具文档。本课禁止把内容当攻击演练脚本。分段下一课缩小可达性。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照 TCP 握手可见性、过滤与黑洞。用扫描结果驱动关闭默认服务。下一课网络分段。</p>',12)),(e(),s(c,null,{default:r(()=>[d(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20ASSET%5B%22%E8%B5%84%E4%BA%A7%E8%8C%83%E5%9B%B4%22%5D%20--%3E%20PROBE%5B%22%E6%8E%A2%E6%B5%8B%E7%9B%91%E5%90%AC%22%5D%0A%20%20PROBE%20--%3E%20INV%5B%22%E6%B8%85%E5%8D%95%22%5D%0A%20%20INV%20--%3E%20CLOSE%5B%22%E5%85%B3%E9%97%AD%E4%B8%8D%E5%BF%85%E8%A6%81%E7%AB%AF%E7%82%B9%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>攻击面度量。分段让即使端口开着也只对该区可见。默认配置下一课继续关不必要服务。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不对他人网络给步骤。网络分段下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>洪水是容量；扫描是发现暴露。</li><li>用于自己的资产盘点与关端口。</li><li>授权范围先于工具。</li><li>下一课网络分段。</li><li>出处：Fyodor, <em>Nmap Network Scanning</em>；RFC 793。</li></ul>',8))])}const T=i(h,[["render",m]]);export{P as __pageData,T as default};
